// Package compat migrates configurations generated by the Nekoray 3.26 GUI.
// Migration happens in memory; the user's saved profiles are never rewritten.
package compat

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type object = map[string]any

func obj(value any) object {
	result, _ := value.(map[string]any)
	return result
}

func list(value any) []any {
	if value == nil {
		return nil
	}
	if result, ok := value.([]any); ok {
		return result
	}
	return []any{value}
}

func str(value any) string {
	result, _ := value.(string)
	return result
}

func appendValues(dst object, key string, values ...any) {
	dst[key] = append(list(dst[key]), values...)
}

func copyIfPresent(dst object, dstKey string, src object, srcKey string) {
	if value, found := src[srcKey]; found {
		dst[dstKey] = value
	}
}

type migrator struct {
	root, route   object
	legacy        bool
	special       map[string]string
	overrides     map[string]object
	dnsRcodes     map[string]string
	dnsStrategies map[string]string
	fakeServers   map[string]bool
	geo           *geoData
}

func Normalize(input []byte) ([]byte, error) {
	decoder := json.NewDecoder(bytes.NewReader(input))
	decoder.UseNumber()
	var root object
	if err := decoder.Decode(&root); err != nil {
		return nil, err
	}
	if root == nil {
		return nil, fmt.Errorf("configuration must be a JSON object")
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		return nil, fmt.Errorf("unexpected data after configuration")
	}
	route := obj(root["route"])
	if route == nil {
		route = object{}
		root["route"] = route
	}
	m := &migrator{
		root: root, route: route,
		special: map[string]string{}, overrides: map[string]object{},
		dnsRcodes: map[string]string{}, dnsStrategies: map[string]string{}, fakeServers: map[string]bool{},
		geo: newGeoData(route),
	}
	defer m.geo.close()
	if err := m.outbounds(); err != nil {
		return nil, err
	}
	if err := m.dns(); err != nil {
		return nil, err
	}
	if err := m.inbounds(); err != nil {
		return nil, err
	}
	if err := m.rules(list(route["rules"]), false); err != nil {
		return nil, err
	}
	if dns := obj(root["dns"]); dns != nil {
		if err := m.rules(list(dns["rules"]), true); err != nil {
			return nil, err
		}
	}
	if action := m.special[str(route["final"])]; action != "" {
		appendValues(route, "rules", object{"action": action})
		delete(route, "final")
	}
	if overrides := m.overrides[str(route["final"])]; overrides != nil {
		rule := object{"outbound": route["final"]}
		for key, value := range overrides {
			rule[key] = value
		}
		appendValues(route, "rules", rule)
	}
	delete(route, "geoip")
	delete(route, "geosite")
	m.dialers()
	return json.MarshalIndent(root, "", "  ")
}

func (m *migrator) outbounds() error {
	var outbounds []any
	for n, value := range list(m.root["outbounds"]) {
		out := obj(value)
		if out == nil {
			return fmt.Errorf("outbounds[%d] must be an object", n)
		}
		kind, tag := str(out["type"]), str(out["tag"])
		switch kind {
		case "dns":
			if tag == "" {
				return fmt.Errorf("legacy %s outbound requires a tag", kind)
			}
			m.special[tag] = "hijack-dns"
			m.legacy = true
			continue
		case "wireguard":
			m.legacy = true
			if err := migrateWireGuard(out); err != nil {
				return err
			}
			appendValues(m.root, "endpoints", out)
			continue
		case "hysteria", "hysteria2":
			if ports, ok := out["hop_ports"]; ok {
				m.legacy = true
				parts := strings.Split(str(ports), ",")
				var ranges []any
				for _, part := range parts {
					if part = strings.TrimSpace(part); part != "" {
						part = strings.ReplaceAll(part, "-", ":")
						if !strings.Contains(part, ":") {
							part += ":" + part
						}
						ranges = append(ranges, part)
					}
				}
				if _, exists := out["server_ports"]; !exists {
					out["server_ports"] = ranges
				}
				delete(out, "hop_ports")
			}
			if value, ok := out["hop_interval"].(json.Number); ok {
				out["hop_interval"] = value.String() + "s"
			}
		case "direct":
			if str(out["override_address"]) != "" || (out["override_port"] != nil && fmt.Sprint(out["override_port"]) != "0") {
				m.overrides[tag] = object{}
				copyIfPresent(m.overrides[tag], "override_address", out, "override_address")
				copyIfPresent(m.overrides[tag], "override_port", out, "override_port")
				m.legacy = true
			}
			delete(out, "override_address")
			delete(out, "override_port")
		}
		outbounds = append(outbounds, out)
	}
	if _, exists := m.root["outbounds"]; exists {
		m.root["outbounds"] = outbounds
	}
	return nil
}

func migrateWireGuard(out object) error {
	copyIfPresent(out, "address", out, "local_address")
	copyIfPresent(out, "system", out, "system_interface")
	copyIfPresent(out, "name", out, "interface_name")
	if out["peers"] == nil {
		peer := object{"allowed_ips": []any{"0.0.0.0/0", "::/0"}}
		for oldKey, newKey := range map[string]string{
			"server": "address", "server_port": "port", "peer_public_key": "public_key",
			"pre_shared_key": "pre_shared_key", "reserved": "reserved",
		} {
			copyIfPresent(peer, newKey, out, oldKey)
		}
		out["peers"] = []any{peer}
	} else {
		for _, value := range list(out["peers"]) {
			peer := obj(value)
			if peer == nil {
				return fmt.Errorf("invalid WireGuard peer")
			}
			copyIfPresent(peer, "address", peer, "server")
			copyIfPresent(peer, "port", peer, "server_port")
			delete(peer, "server")
			delete(peer, "server_port")
		}
	}
	for _, key := range []string{"local_address", "system_interface", "interface_name", "server", "server_port", "peer_public_key", "pre_shared_key", "reserved", "network", "gso"} {
		delete(out, key)
	}
	return nil
}

func (m *migrator) inbounds() error {
	var prefix []any
	for n, value := range list(m.root["inbounds"]) {
		in := obj(value)
		if in == nil {
			return fmt.Errorf("inbounds[%d] must be an object", n)
		}
		tag := str(in["tag"])
		if tag == "" && (in["sniff"] == true || str(in["domain_strategy"]) != "") {
			tag = "nekoray-inbound-" + strconv.Itoa(n)
			in["tag"] = tag
		}
		strategy := str(in["domain_strategy"])
		if strategy != "" && strategy != "as_is" {
			prefix = append(prefix, object{"inbound": tag, "action": "resolve", "strategy": strategy})
		}
		if in["sniff"] == true {
			rule := object{"inbound": tag, "action": "sniff"}
			copyIfPresent(rule, "timeout", in, "sniff_timeout")
			prefix = append(prefix, rule)
		}
		for _, key := range []string{"sniff", "sniff_timeout", "sniff_override_destination", "domain_strategy"} {
			if _, ok := in[key]; ok {
				m.legacy = true
				delete(in, key)
			}
		}
		if str(in["type"]) == "tun" {
			for newKey, oldKeys := range map[string][]string{
				"address":               {"inet4_address", "inet6_address"},
				"route_address":         {"inet4_route_address", "inet6_route_address"},
				"route_exclude_address": {"inet4_route_exclude_address", "inet6_route_exclude_address"},
			} {
				for _, key := range oldKeys {
					if value, ok := in[key]; ok {
						m.legacy = true
						appendValues(in, newKey, list(value)...)
						delete(in, key)
					}
				}
			}
			delete(in, "endpoint_independent_nat")
		}
	}
	if len(prefix) > 0 {
		m.route["rules"] = append(prefix, list(m.route["rules"])...)
	}
	return nil
}

func (m *migrator) rules(rules []any, dns bool) error {
	for n, value := range rules {
		rule := obj(value)
		if rule == nil {
			return fmt.Errorf("rules[%d] must be an object", n)
		}
		if nested := rule["rules"]; nested != nil {
			if err := m.rules(list(nested), dns); err != nil {
				return err
			}
		}
		if err := m.geo.expand(rule); err != nil {
			return err
		}
		if dns {
			server := str(rule["server"])
			if code, ok := m.dnsRcodes[server]; ok {
				delete(rule, "server")
				rule["action"] = "predefined"
				rule["rcode"] = code
			} else {
				if strategy := m.dnsStrategies[server]; strategy != "" && rule["strategy"] == nil {
					rule["strategy"] = strategy
				}
				if m.fakeServers[server] && rule["query_type"] == nil {
					rule["query_type"] = []any{"A", "AAAA"}
				}
			}
			if len(list(rule["outbound"])) > 0 {
				return fmt.Errorf("legacy DNS rule with outbound matching requires migration to domain_resolver")
			}
		} else {
			tag := str(rule["outbound"])
			if action := m.special[tag]; action != "" {
				delete(rule, "outbound")
				rule["action"] = action
			}
			for key, value := range m.overrides[tag] {
				if _, exists := rule[key]; !exists {
					rule[key] = value
				}
			}
		}
	}
	return nil
}

func (m *migrator) dialers() {
	if !m.legacy {
		return
	}
	dns := obj(m.root["dns"])
	if dns == nil {
		dns = object{}
		m.root["dns"] = dns
	}
	servers := list(dns["servers"])
	bootstrap, defaultServer := "", str(dns["final"])
	for _, value := range servers {
		server := obj(value)
		if server == nil {
			continue
		}
		if defaultServer == "" && str(server["type"]) != "fakeip" {
			defaultServer = str(server["tag"])
		}
		if str(server["tag"]) == "dns-local" || (bootstrap == "" && str(server["type"]) == "local") {
			bootstrap = str(server["tag"])
		}
	}
	if bootstrap == "" {
		bootstrap = "nekoray-bootstrap"
		existing := map[string]bool{}
		for _, value := range servers {
			existing[str(obj(value)["tag"])] = true
		}
		for existing[bootstrap] {
			bootstrap += "-"
		}
		appendValues(dns, "servers", object{"type": "local", "tag": bootstrap})
	}
	if defaultServer == "" {
		defaultServer = bootstrap
	}
	if m.route["default_domain_resolver"] == nil {
		m.route["default_domain_resolver"] = defaultServer
	}
	for _, collection := range []string{"outbounds", "endpoints"} {
		for _, value := range list(m.root[collection]) {
			out := obj(value)
			if out == nil {
				continue
			}
			strategy, exists := out["domain_strategy"]
			if exists || str(out["server"]) != "" {
				if out["domain_resolver"] == nil {
					resolver := object{"server": bootstrap}
					if str(strategy) != "" {
						resolver["strategy"] = strategy
					}
					out["domain_resolver"] = resolver
				}
			}
			delete(out, "domain_strategy")
		}
	}
}
